local a={}local b={}function mtime(c)local d=ffi.C.CreateFileA(c,0x80000000,3,nil,3,0x80,nil)if tonumber(ffi.cast("intptr_t",d))==-1 then return nil end;local e=ffi.new("FILETIME[1]")local f=ffi.C.GetFileTime(d,nil,nil,e)ffi.C.CloseHandle(d)if f==0 then return nil end;return tonumber(e[0].dwHighDateTime)*4294967296+tonumber(e[0].dwLowDateTime)end;function string:trim()return self:match("^%s*(.-)%s*$")end;function noExt(g)g=g:gsub("%.+",".")if g:lower():match("%.luac$")then g=g:sub(1,-6)elseif g:lower():match("%.lua$")then g=g:sub(1,-5)end;return g end;local h=getWorkingDirectory().."/moduler"if not doesDirectoryExist(h)then createDirectory(h)end;function printErr(i)print("{ff7070}(error): {c0c0c0}"..i)end;function isScrLoaded(j)for k,l in pairs(script.list())do if noExt(l.name:lower():trim())==noExt(j:lower():trim())then return l end end;return false end;function extractSubmodule(m,n)m=m:gsub("\r\n","\n"):gsub("\r","\n")local o="%-%-%s*[Mm]oduler:%s*"..n.."%s*\n"local p,q=m:find("^"..o)if not p then p,q=m:find("\n"..o)end;if not p then return nil end;local r=q+1;local s=m:find("\n%-%-%s*[Mm]oduler:%s*[_%w]+%s*\n",r)local t=m:sub(r,s and s-1 or#m)t=t:gsub("^\n+",""):gsub("\n+$","")return t end;function findModulerCalls(u)local v={}local w={}local x=1;while true do local p=u:find("%-%-%[%[",x)if not p then break end;local s=u:find("%]%]",p+4)if s then table.insert(w,{s=p,e=s+1})x=s+2 else break end end;local function y(z)for A,B in ipairs(w)do if z>=B.s and z<=B.e then return true end end;return false end;for C,D in u:gmatch('(moduler%s*%(%s*["\']([^"\']+)["\']%s*%))')do local E=u:find(C,1,true)if E and not y(E)then local F=u:sub(1,E):match(".*\n()")or 1;local G=u:sub(F,E-1)if not G:match("^%s*%-%-")then local H=G:match('^([ \t]*)')table.insert(v,{module=D,indent=H or""})end end end;return v end;function applyIndentation(I,H)local J={}for K in(I.."\n"):gmatch("([^\r\n]*)\r?\n")do table.insert(J,K)end;if#J>0 then local L=nil;for A,K in ipairs(J)do if K:match("%S")then local M=K:match("^([ \t]*)")if not L or#M<#L then L=M end end end;if L and#L>0 then local N={}for A,K in ipairs(J)do if K:sub(1,#L)==L then table.insert(N,K:sub(#L+1))else table.insert(N,K)end end;J=N end end;if H==""then return table.concat(J,"\n")end;local O={}for A,K in ipairs(J)do table.insert(O,H..K)end;return table.concat(O,"\n")end;function build(j)j=noExt(j)local P=getWorkingDirectory()local h=P.."/moduler"local Q=h.."/"..j;local R=P.."/"..j..".lua"if not doesFileExist(R)then printErr('Script "'..j..'.lua" not found')return false end;local S={[R]=mtime(R)}local T=io.open(R,"rb")if not T then printErr("Error opening script: "..j)return false end;local U=T:read("*a")T:close()if#U==0 then printErr(string.format('Script "%s" is empty.',j))return false end;local V=U:sub(1,4)if not V then printErr("No header found in script: "..j)return false end;if V=="\27Lua"or V=="\27LJ"then printErr(string.format('Script "%s" not supported as it is compiled. Use plain lua script.',j))return false end;local W=findModulerCalls(U)if#W==0 then print('No moduler() calls found in "'..j..'"')local X,Y=loadstring(U,j..".lua")if not X then printErr("Syntax error in "..j..": "..Y)return false end;local f,Z=pcall(X)if not f then printErr(string.format('Error executing script: "%s": %s',j,Z))return false end;return true end;print('{44bbff}Moduler: {c0c0c0}Building "'..j..'" with '..#W..' (sub)module calls...')local _={}for A,a0 in ipairs(W)do local a1,H=a0.module,a0.indent;local D=noExt(a1)local n=nil;if D:match("%.",1,true)then local a2={}for z in D:gmatch("[^%.]+")do table.insert(a2,z)end;if#a2>2 then printErr("Submodule nesting too deep: "..a1)return false end;D=a2[1]n=#a2==2 and a2[2]:trim()or nil;if n and(n:match("%[")or n:match("%]"))then printErr(string.format('Submodule "%s" in module "%s" in script "%s" has an invalid name.',n,D,j))return false end end;local a3=Q.."/"..D..".lua"if not doesFileExist(a3)then printErr(string.format('Module "%s" not found for script "%s"',D,j))return