se()end;local ai,aj=pcall(function()script.load(ab)end)if not ai then printErr("Error loading the built "..j..": "..aj)return false end;a[j]=S;b[j]=nil;return true end;local ak=0;function _load(j)ak=ak+1;if ak>loadTryMax then return false end;local al=isScrLoaded(j)if al then local f=pcall(function()al:unload()end)if not f then printErr("Failed Unloading: "..j)return false end;local am,an=pcall(lua_thread.create,function()wait(100)_load(j)end)return false end;local P=getWorkingDirectory()local h=P.."/moduler"local Q=h.."/"..j;if not doesDirectoryExist(h)then createDirectory(h)printErr('No Modules found for "'..j..'"')return false end;if not doesDirectoryExist(Q)then printErr('No Modules found for "'..j..'"')return false end;return build(j)end;function load(j)ak=0;local j=j and noExt(j:trim())or nil;if not j or j==""or j:lower()=="moduler"then return false end;return _load(j)end;function checkChanged()for j,S in pairs(a)do local ao=false;for c,ap in pairs(S)do local aq=mtime(c)if aq and aq~=ap then S[c]=aq;ao=true end end;if ao then if isScrLoaded(j)or b[j]then b[j]=true;print('{44bbff}Moduler: {c0c0c0}Change detected. Rebuilding "'..j..'"')load(j)else a[j]=nil;b[j]=nil end end end end;function main()if not isSampLoaded()or not isSampfuncsLoaded()then return end;while not isSampAvailable()do wait(0)end;sampRegisterChatCommand("moduler",function(j)local j=j and noExt(j:trim())or nil;if not j or j==""or j:lower()=="moduler"then return false end;if a[j]then a[j]=nil end;load(j)end)sampRegisterChatCommand("modulerlist",function()local ar=0;for j,S in pairs(a)do ar=ar+1;print("--------------------")print("Script: "..j)local as=0;local P=getWorkingDirectory()for c,ap in pairs(S)do local at=c;if at:sub(1,#P):lower()==P:lower()then at=at:sub(#P+1)end;at=at:gsub("^[\\/]",""):gsub("^moduler/","")local au="Module:"if at:lower()==j:lower()..".lua"then au="Parent:"else as=as+1;at=at:sub(#j+2)end;print(string.format("%s %s, T: %.0f",au,at,ap))end;print("Total Modules: "..as)print("--------------------")end;if ar~=0 then print("Total Scripts: "..ar)end;sampAddChatMessage("Total Scripts: "..ar..(ar~=0 and". {bbbbbb}Check sampfuncs console prints for details."or""),-1)end)local av=os.clock()local aw=av;while true do wait(1000)local ax=os.clock()if ax-av>tabGap or ax-aw>=checkInterval then aw=ax;checkChanged()end;av=ax end end;EXPORTS={load=load}
